USE [DeineDatenbank];
GO
DECLARE @CiFileMarker nvarchar(400)=CONCAT(N'CI_BEGIN|207|file|0|',CONVERT(varchar(27),SYSUTCDATETIME(),126),N'Z|',@@SPID,N'|',@@LOCK_TIMEOUT,N'|-');
RAISERROR(N'%s',10,1,@CiFileMarker) WITH NOWAIT;
GO
-- K1-K9 lookup/cache contracts use a new synthetic source; no SSIS package execution.
DECLARE @DbId int=DB_ID(),@OuterOptions int=@@OPTIONS,@OuterLock int=@@LOCK_TIMEOUT,@OuterTran int=@@TRANCOUNT;
IF OBJECT_ID(N'dbo.ExampleLookupCacheLogSource') IS NOT NULL OR OBJECT_ID(N'dbo.ExampleLookupCacheFixtureScope') IS NOT NULL OR OBJECT_ID(N'tempdb..#ExampleLookupCacheOwnership') IS NOT NULL OR DATABASE_PRINCIPAL_ID(N'ExampleLookupCacheReader') IS NOT NULL THROW 56990,N'K_SOURCE_COLLISION',1;
CREATE TABLE #ExampleLookupCacheOwnership(TableId int NULL,UserId int NULL);INSERT #ExampleLookupCacheOwnership VALUES(NULL,NULL);
DECLARE @OwnershipId int=OBJECT_ID(N'tempdb..#ExampleLookupCacheOwnership'),@TableId int,@ProcId int;
BEGIN TRY
 EXEC(N'CREATE PROCEDURE dbo.ExampleLookupCacheFixtureScope @OwnedTableId int OUTPUT AS BEGIN

SET NOCOUNT ON;
DECLARE @CiOrdinal int=0,@CiMarker nvarchar(1000);
DECLARE @Db sysname=DB_NAME(),@Id uniqueidentifier=NEWID(),@A uniqueidentifier=NEWID(),@T datetime=''20000101'';
DECLARE @InitialOptions int=@@OPTIONS,@InitialLock int=@@LOCK_TIMEOUT,@InitialTran int=@@TRANCOUNT;
CREATE TABLE dbo.ExampleLookupCacheLogSource(id int NOT NULL,event nvarchar(128) COLLATE SQL_Latin1_General_CP1_CS_AS NULL,source nvarchar(128) COLLATE SQL_Latin1_General_CP1_CS_AS NULL,sourceid uniqueidentifier NULL,executionid uniqueidentifier NULL,starttime datetime NULL,endtime datetime NULL,datacode int NULL,message nvarchar(max) COLLATE SQL_Latin1_General_CP1_CS_AS NULL);
SET @OwnedTableId=OBJECT_ID(N''dbo.ExampleLookupCacheLogSource'');UPDATE #ExampleLookupCacheOwnership SET TableId=@OwnedTableId;
DECLARE @J nvarchar(max),@Status varchar(40),@Partial bit,@Error int,@Message nvarchar(4000),@CallSeq int=0;
DECLARE @F int=0,@Task bit,@Row bit,@Phase bit,@Life bit,@Lookup bit,@Version int;
WHILE @F<32
BEGIN
 SELECT @Task=CONVERT(bit,@F&1),@Row=CONVERT(bit,@F&2),@Phase=CONVERT(bit,@F&4),@Life=CONVERT(bit,@F&8),@Lookup=CONVERT(bit,@F&16);
 SELECT @J=NULL,@Status=NULL,@Partial=NULL,@Error=NULL,@Message=NULL;
SET @CiOrdinal+=1; SET @CiMarker=CONCAT(N''CI_CASE|207|C001|'',@CiOrdinal,N''|'',CONVERT(varchar(27),SYSUTCDATETIME(),126),N''Z|'',@@SPID,N''|'',@@LOCK_TIMEOUT,N''|'',LEFT(CONCAT(N''F='',@F,N'';'',N''''),180)); RAISERROR(N''%s'',10,1,@CiMarker) WITH NOWAIT;
EXEC [monitor].[USP_SsisLegacyLogAnalysis] @LoggingDatabase=@Db,@LoggingTable=N''ExampleLookupCacheLogSource'',@ExecutionId=@Id,@IncludeTaskAnalysis=@Task,@IncludeRowFlowAnalysis=@Row,@IncludeComponentPhaseAnalysis=@Phase,@IncludeComponentLifecyclePhases=@Life,@IncludeLookupCacheAnalysis=@Lookup,@MaxZeilen=0,@HighImpactConfirmed=1,@ResultSetArt=''NONE'',@JsonErzeugen=1,@Json=@J OUTPUT,@StatusCodeOut=@Status OUTPUT,@ErrorNumberOut=@Error OUTPUT,@PrintMeldungen=0,@IsPartialOut=@Partial OUTPUT,@ErrorMessageOut=@Message OUTPUT; SET @CiMarker=CONCAT(N''CI_AFTER|207|C001|'',@CiOrdinal,N''|'',CONVERT(varchar(27),SYSUTCDATETIME(),126),N''Z|'',@@SPID,N''|'',@@LOCK_TIMEOUT,N''|'',LEFT(CONCAT(N''F='',@F,N'';'',N''''),180)); RAISERROR(N''%s'',10,1,@CiMarker) WITH NOWAIT;
SET @CallSeq+=1;SELECT N''K-CALL-Capture'' AS CaptureLabel,@CallSeq AS CallOrdinal,@J AS CaptureJson,@Status AS OutputStatus,@Partial AS OutputPartial,@Error AS OutputError,@Message AS OutputMessage,@@OPTIONS AS CallerOptions,@@LOCK_TIMEOUT AS CallerLockTimeout,@@TRANCOUNT AS CallerTranCount,XACT_STATE() AS CallerXactState,DB_ID() AS CallerDatabaseId,CONVERT(varchar(172),SUSER_SID(),1) AS CallerSid,OBJECT_ID(N''dbo.ExampleLookupCacheLogSource'') AS OwnSourceTableId,OBJECT_ID(N''dbo.ExampleLookupCacheFixtureScope'') AS OwnFixtureProcedureId;
IF ISNULL(ISJSON(@J),0)<>1 THROW 56940,N''K_CURRENT_JSON_INVALID'',1;
IF @Lookup=1 AND NOT EXISTS(SELECT 1 FROM OPENJSON(@J) WHERE [key] COLLATE SQL_Latin1_General_CP1_CS_AS=N''lookupCacheEvents'' AND [type]=4) THROW 56941,N''K_ACTIVE_ARRAY_TYPE'',1;

 IF @Life=1 AND @Phase=0 BEGIN IF ISNULL(@Status,'''')<>''INVALID_PARAMETER'' OR EXISTS(SELECT 1 FROM OPENJSON(@J,''$.sourceStatus'') WHERE JSON_VALUE(value,''$.StatusCode'')<>''NOT_READ'') THROW 56901,N''K_FLAG_DEPENDENCY'',1;END
 ELSE BEGIN
  SET @Version=CASE WHEN @Lookup=1 THEN 6 WHEN @Life=1 THEN 5 WHEN @Phase=1 THEN 4 WHEN @Row=1 THEN 3 WHEN @Task=1 THEN 2 ELSE 1 END;
  IF ISNULL(TRY_CONVERT(int,JSON_VALUE(@J,''$.meta.SchemaVersion'')),-1)<>@Version THROW 56902,N''K_FLAG_VERSION'',1;
 END;
 IF (@Lookup=0 AND EXISTS(SELECT 1 FROM OPENJSON(@J) WHERE [key]=N''lookupCacheEvents'')) OR (@Lookup=1 AND (JSON_QUERY(@J,''$.lookupCacheEvents'') IS NULL OR ISNULL(JSON_VALUE(@J,''$.meta.LookupCacheCatalogVersion''),N''MISSING'')<>N''1'')) THROW 56903,N''K_FLAG_KEYS'',1;
 SET @F+=1;
END;
SELECT @J=NULL,@Status=NULL,@Partial=NULL,@Error=NULL,@Message=NULL;
SET @CiOrdinal+=1; SET @CiMarker=CONCAT(N''CI_CASE|207|C002|'',@CiOrdinal,N''|'',CONVERT(varchar(27),SYSUTCDATETIME(),126),N''Z|'',@@SPID,N''|'',@@LOCK_TIMEOUT,N''|'',LEFT(CONCAT(N''F='',@F,N'';'',N''''),180)); RAISERROR(N''%s'',10,1,@CiMarker) WITH NOWAIT;
EXEC [monitor].[USP_SsisLegacyLogAnalysis] @LoggingDatabase=@Db,@LoggingTable=N''ExampleLookupCacheLogSource'',@ExecutionId=@Id,@IncludeLookupCacheAnalysis=NULL,@HighImpactConfirmed=1,@ResultSetArt=''NONE'',@JsonErzeugen=1,@Json=@J OUTPUT,@PrintMeldungen=0,@StatusCodeOut=@Status OUTPUT,@IsPartialOut=@Partial OUTPUT,@ErrorNumberOut=@Error OUTPUT,@ErrorMessageOut=@Message OUTPUT; SET @CiMarker=CONCAT(N''CI_AFTER|207|C002|'',@CiOrdinal,N''|'',CONVERT(varchar(27),SYSUTCDATETIME(),126),N''Z|'',@@SPID,N''|'',@@LOCK_TIMEOUT,N''|'',LEFT(CONCAT(N''F='',@F,N'';'',N''''),180)); RAISERROR(N''%s'',10,1,@CiMarker) WITH NOWAIT;
SET @CallSeq+=1;SELECT N''K-CALL-Capture'' AS CaptureLabel,@CallSeq AS CallOrdinal,@J AS CaptureJson,@Status AS OutputStatus,@Partial AS OutputPartial,@Error AS OutputError,@Message AS OutputMessage,@@OPTIONS AS CallerOptions,@@LOCK_TIMEOUT AS CallerLockTimeout,@@TRANCOUNT AS CallerTranCount,XACT_STATE() AS CallerXactState,DB_ID() AS CallerDatabaseId,CONVERT(varchar(172),SUSER_SID(),1) AS CallerSid,OBJECT_ID(N''dbo.ExampleLookupCacheLogSource'') AS OwnSourceTableId,OBJECT_ID(N''dbo.ExampleLookupCacheFixtureScope'') AS OwnFixtureProcedureId;
IF ISNULL(ISJSON(@J),0)<>1 THROW 56940,N''K_CURRENT_JSON_INVALID'',1;
IF 1=0 AND NOT EXISTS(SELECT 1 FROM OPENJSON(@J) WHERE [key] COLLATE SQL_Latin1_General_CP1_CS_AS=N''lookupCacheEvents'' AND [type]=4) THROW 56941,N''K_ACTIVE_ARRAY_TYPE'',1;

IF EXISTS(SELECT 1 FROM OPENJSON(@J) WHERE [key]=N''lookupCacheEvents'') THROW 56904,N''K_NULL_FLAG'',1;
SET @J=N''OLD'';SET @Status=''OLD'';SET @Partial=1;SET @Error=1;SET @Message=N''OLD'';
SET @CiOrdinal+=1; SET @CiMarker=CONCAT(N''CI_CASE|207|C003|'',@CiOrdinal,N''|'',CONVERT(varchar(27),SYSUTCDATETIME(),126),N''Z|'',@@SPID,N''|'',@@LOCK_TIMEOUT,N''|'',LEFT(CONCAT(N''F='',@F,N'';'',N''''),180)); RAISERROR(N''%s'',10,1,@CiMarker) WITH NOWAIT;
EXEC [monitor].[USP_SsisLegacyLogAnalysis] @Hilfe=1,@IncludeLookupCacheAnalysis=1,@Json=@J OUTPUT,@StatusCodeOut=@Status OUTPUT,@IsPartialOut=@Partial OUTPUT,@ErrorNumberOut=@Error OUTPUT,@ErrorMessageOut=@Message OUTPUT; SET @CiMarker=CONCAT(N''CI_AFTER|207|C003|'',@CiOrdinal,N''|'',CONVERT(varchar(27),SYSUTCDATETIME(),126),N''Z|'',@@SPID,N''|'',@@LOCK_TIMEOUT,N''|'',LEFT(CONCAT(N''F='',@F,N'';'',N''''),180)); RAISERROR(N''%s'',10,1,@CiMarker) WITH NOWAIT;
SET @CallSeq+=1;SELECT N''K-CALL-Capture'' AS CaptureLabel,@CallSeq AS CallOrdinal,@J AS CaptureJson,@Status AS OutputStatus,@Partial AS OutputPartial,@Error AS OutputError,@Message AS OutputMessage,@@OPTIONS AS CallerOptions,@@LOCK_TIMEOUT AS CallerLockTimeout,@@TRANCOUNT AS CallerTranCount,XACT_STATE() AS CallerXactState,DB_ID() AS CallerDatabaseId,CONVERT(varchar(172),SUSER_SID(),1) AS CallerSid,OBJECT_ID(N''dbo.ExampleLookupCacheLogSource'') AS OwnSourceTableId,OBJECT_ID(N''dbo.ExampleLookupCacheFixtureScope'') AS OwnFixtureProcedureId;

IF @J IS NOT NULL OR @Status IS NOT NULL OR @Partial IS NOT NULL OR @Error IS NOT NULL OR @Message IS NOT NULL THROW 56905,N''K_HELP'',1;
IF NOT EXISTS(SELECT 1 FROM sys.parameters WHERE object_id=OBJECT_ID(N''monitor.USP_SsisLegacyLogAnalysis'') AND parameter_id=25 AND name COLLATE SQL_Latin1_General_CP1_CS_AS=N''@IncludeLookupCacheAnalysis'') THROW 56906,N''K_POSITION25'',1;
