IF ISNULL(JSON_QUERY(@J,''$.lookupCacheEvents''),N''MISSING'')<>N''[]'' OR NOT EXISTS(SELECT 1 FROM OPENJSON(@J,''$.sourceStatus'') WHERE JSON_VALUE(value,''$.SourceName'')=N''lookupCacheAnalysis'' AND JSON_VALUE(value,''$.Detail'')=N''NO_VALID_EVENT_BUFFER'') THROW 56945,N''K_MISSING_SOURCE'',1;
SELECT N''PASS'' AS LookupAdditionalStatus,8 AS SeparateReports,23 AS IndependentFields,2 AS SourceBoundaries;
SELECT N''PASS'' AS LookupCacheSyntheticStatus,207 AS PayloadCases,32 AS FlagCases,23 AS IndependentFields;
 END;');
 SET @ProcId=OBJECT_ID(N'dbo.ExampleLookupCacheFixtureScope');
 EXEC dbo.ExampleLookupCacheFixtureScope @OwnedTableId=@TableId OUTPUT;
 IF DB_ID()<>@DbId OR OBJECT_ID(N'dbo.ExampleLookupCacheLogSource')<>@TableId OR OBJECT_ID(N'dbo.ExampleLookupCacheFixtureScope')<>@ProcId THROW 56991,N'K_CLEANUP_BINDING',1;
 DROP TABLE dbo.ExampleLookupCacheLogSource;DROP PROCEDURE dbo.ExampleLookupCacheFixtureScope;
 IF @@OPTIONS<>@OuterOptions OR @@LOCK_TIMEOUT<>@OuterLock OR @@TRANCOUNT<>@OuterTran THROW 56992,N'K_OUTER_CALLER',1;
END TRY BEGIN CATCH
 DECLARE @Err int=ERROR_NUMBER(),@Msg nvarchar(4000)=ERROR_MESSAGE(),@Cleanup nvarchar(4000)=N'',@UserId int;
 DECLARE @OwnScope bit=0;
 BEGIN TRY
  IF DB_ID()<>@DbId OR OBJECT_ID(N'tempdb..#ExampleLookupCacheOwnership')<>@OwnershipId THROW 56993,N'K_FAILURE_SCOPE',1;
  SELECT @TableId=TableId,@UserId=UserId FROM #ExampleLookupCacheOwnership;SET @OwnScope=1;
 END TRY BEGIN CATCH SET @Cleanup=CONCAT(@Cleanup,N'Scope:',ERROR_MESSAGE(),N';');END CATCH;
 IF @OwnScope=1
 BEGIN
  BEGIN TRY IF @UserId IS NOT NULL AND DATABASE_PRINCIPAL_ID(N'ExampleLookupCacheReader')=@UserId DROP USER ExampleLookupCacheReader;END TRY BEGIN CATCH SET @Cleanup=CONCAT(@Cleanup,N'User:',ERROR_MESSAGE(),N';');END CATCH;
  BEGIN TRY IF @TableId IS NOT NULL AND OBJECT_ID(N'dbo.ExampleLookupCacheLogSource')=@TableId DROP TABLE dbo.ExampleLookupCacheLogSource;END TRY BEGIN CATCH SET @Cleanup=CONCAT(@Cleanup,N'Table:',ERROR_MESSAGE(),N';');END CATCH;
  BEGIN TRY IF @ProcId IS NOT NULL AND OBJECT_ID(N'dbo.ExampleLookupCacheFixtureScope')=@ProcId DROP PROCEDURE dbo.ExampleLookupCacheFixtureScope;END TRY BEGIN CATCH SET @Cleanup=CONCAT(@Cleanup,N'Proc:',ERROR_MESSAGE(),N';');END CATCH;
  BEGIN TRY IF OBJECT_ID(N'tempdb..#ExampleLookupCacheOwnership')=@OwnershipId DROP TABLE #ExampleLookupCacheOwnership;END TRY BEGIN CATCH SET @Cleanup=CONCAT(@Cleanup,N'Temp:',ERROR_MESSAGE(),N';');END CATCH;
 END;
 SELECT @Err AS OriginalError,@Msg AS OriginalMessage,@Cleanup AS CleanupError;THROW;
END CATCH;
DROP TABLE #ExampleLookupCacheOwnership;
DECLARE @CiFileMarker nvarchar(400)=CONCAT(N'CI_END|207|file|0|',CONVERT(varchar(27),SYSUTCDATETIME(),126),N'Z|',@@SPID,N'|',@@LOCK_TIMEOUT,N'|-');
RAISERROR(N'%s',10,1,@CiFileMarker) WITH NOWAIT;
